26	/// What to search for and where.
27	#[derive(Clone, Copy, Debug)]
28	pub struct SearchRequest<'a> {
29	    /// The directory to search; it is canonicalized first.
30	    pub root: &'a Utf8Path,
31	    /// The query text, in the syntax [`parse`] reads, or a literal when `exact` is set.
32	    pub query: &'a str,
33	    /// Treats the whole query as one literal term, operators and quotes included.
34	    pub exact: bool,
35	    /// Searches test files too, and test code inside source files: Rust items under `#[cfg(test)]` or `#[test]`.
36	    pub allow_tests: bool,
37	    /// Skips hidden files and what `.gitignore` and `.ignore` files exclude: inside the root and, within a git
38	    /// repository, in its parent directories up to the repository root.
39	    pub respect_ignore_files: bool,
40	    /// Restricts the search to one language; only TypeScript, JavaScript and Rust are supported.
41	    pub language: Option<Language>,
42	}
43	
44	/// Everything a search found, best first and uncapped.
45	#[derive(Clone, Debug)]
46	pub struct SearchResult {
47	    /// Deduplicated blocks with 1-based, contiguous ranks.
48	    pub ranked: Vec<RankedBlock>,
49	    /// Files with at least one line matching a positive term, kept or not.
50	    pub files_total: u64,
51	    /// Whether `files_total` exceeded the file ceiling, so some matching files were never examined.
52	    pub ceiling_hit: bool,
53	    /// What was skipped or only partly understood, in a deterministic order.
54	    pub diagnostics: Vec<Diagnostic>,
55	}
56	
57	impl SearchResult {
58	    fn empty() -> Self {
59	        Self { ranked: Vec::new(), files_total: 0, ceiling_hit: false, diagnostics: Vec::new() }
60	    }
61	
62	    fn skipped(message: impl Into<String>) -> Self {
63	        Self { diagnostics: vec![skipped(None, message)], ..Self::empty() }
64	    }
65	}
66	
67	/// Runs a search over `request.root` and returns ranked blocks.
68	///
69	/// Text search finds the lines matching the query's positive terms; files with a line matching an excluded term, or
70	/// lacking a match for a required term, drop out. Each remaining file goes to the analyzer that owns it, and only
71	/// blocks containing a matching line are kept, ranked with BM25 and deduplicated. A matching line belongs to the
72	/// smallest block containing it, so a class or object literal keeps only the matches outside its members and is
73	/// dropped when it has none. Files no analyzer supports are ignored without a diagnostic.
74	///
75	/// BM25 query terms are the lowercase [`tokenize`] output of each non-excluded literal term. Regex terms select
76	/// lines and appear in `matched_keywords` but add no BM25 terms. A query with only excluded terms has nothing to
77	/// search for and returns an empty result with one `Skipped` diagnostic.
78	///
79	/// # Errors
80	///
81	/// - [`MonoklError::TooManyTerms`] if the query has too many terms.
82	/// - [`MonoklError::RegexBuild`] if any term is not a valid regex; no file is read first.
83	/// - [`MonoklError::Io`] or [`MonoklError::NonUtf8Path`] if `request.root` cannot be canonicalized.
84	/// - [`MonoklError::Walk`] if the root is not a listable directory.
85	///
86	/// # Examples
87	///
88	/// ```
89	/// use camino::Utf8Path;
90	/// use monokl::analysis::registry::AnalyzerRegistry;
91	/// use monokl::pipeline::{SearchRequest, search};
92	///
93	/// let dir = tempfile::tempdir()?;
94	/// std::fs::write(dir.path().join("a.ts"), "const alpha = 1;\n")?;
95	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
96	/// let request = SearchRequest {
97	///     root,
98	///     query: "alpha",
99	///     exact: false,
100	///     allow_tests: false,
101	///     respect_ignore_files: true,
102	///     language: None,
103	/// };
104	///
105	/// // With no analyzer registered, the file matches but yields no blocks.
106	/// let result = search(&AnalyzerRegistry::new(Vec::new()), &request)?;
107	/// assert_eq!(result.files_total, 1);
108	/// assert!(result.ranked.is_empty());
109	/// # Ok::<(), Box<dyn std::error::Error>>(())
110	/// ```
111	pub fn search(registry: &AnalyzerRegistry, request: &SearchRequest<'_>) -> Result<SearchResult> {
112	    search_with_ceiling(registry, request, DEFAULT_MAX_FILES)
113	}
114	
115	/// A block annotated with its matches, and its tokens.
116	type Candidate = (CodeBlock, Vec<String>);
117	
118	/// [`search`] with the file ceiling as a parameter, so tests can reach it without 100,000 files.
119	fn search_with_ceiling(
