130	                )));
131	            }
132	            Some(id) if !registry.handles(id) => {
133	                return Ok(SearchResult::skipped(format!("language {language:?} has no analyzer in this build")));
134	            }
135	            Some(_) => {}
136	        }
137	    }
138	
139	    let terms = if exact {
140	        if query.trim().is_empty() {
141	            Vec::new()
142	        } else {
143	            vec![ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(query), is_regex: false }]
144	        }
145	    } else {
146	        parse(query)?
147	    };
148	    let plan = QueryPlan::from_terms(terms);
149	    let patterns = plan.search_patterns();
150	    if patterns.is_empty() {
151	        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
152	    }
