226	/// The analyzer language that serves `language` in v1, or `None` when no analyzer path exists for it.
227	fn analyzer_language(language: Language) -> Option<LanguageId> {
228	    match language {
229	        Language::TypeScript | Language::JavaScript => Some(LanguageId::TypeScript),
230	        Language::Rust => Some(LanguageId::Rust),
231	        Language::Python => None,
232	    }
233	}
234	
235	/// Compiles one term the way text search does, case-insensitively, so a term can never match differently here.
236	fn compile(pattern: &str) -> Result<RegexMatcher> {
237	    Ok(RegexMatcherBuilder::new().case_insensitive(true).build(pattern)?)
238	}
239	
240	fn canonicalize(root: &Utf8Path) -> Result<Utf8PathBuf> {
241	    let path = root.as_std_path().canonicalize().map_err(|source| FileIoError::read(root, source))?;
242	    Utf8PathBuf::from_path_buf(path).map_err(|path| MonoklError::NonUtf8Path { path })
243	}
244	
245	/// A file's text, and whether getting it meant replacing bytes that are not UTF-8.
246	struct Source {
247	    text: String,
248	    lossy: bool,
249	}
250	
251	/// Reads `path`, replacing each invalid UTF-8 sequence with U+FFFD so the file is still searched and extracted.
252	fn read_source(path: &Utf8Path) -> io::Result<Source> {
253	    let bytes = std::fs::read(path)?;
254	    Ok(match String::from_utf8(bytes) {
255	        Ok(text) => Source { text, lossy: false },
256	        Err(err) => Source { text: String::from_utf8_lossy(err.as_bytes()).into_owned(), lossy: true },
257	    })
258	}
259	
260	/// Whether `matcher` matches `text`. Matching in memory cannot fail, so an error counts as no match.
261	fn matches_text(matcher: &RegexMatcher, text: &str) -> bool {
262	    matches!(matcher.is_match(text.as_bytes()), Ok(true))
263	}
264	
265	fn skipped(path: Option<&Utf8Path>, message: impl Into<String>) -> Diagnostic {
266	    Diagnostic { kind: DiagnosticKind::Skipped, path: path.map(Utf8Path::to_owned), message: message.into() }
267	}
268	
269	fn unreadable_diagnostic(path: &Utf8Path) -> Diagnostic {
270	    skipped(Some(path), "file could not be read")
271	}
272	
273	/// Turns what text search could not read into diagnostics: one per unreadable path, then one per non-zero count.
274	fn text_search_diagnostics(found: &TextSearchResult) -> Vec<Diagnostic> {
275	    let mut diagnostics: Vec<Diagnostic> = found.unreadable.iter().map(|path| unreadable_diagnostic(path)).collect();
276	    if found.non_utf8_paths > 0 {
277	        diagnostics.push(skipped(None, format!("{} files skipped: path is not valid UTF-8", found.non_utf8_paths)));
278	    }
279	    if found.walk_errors_without_path > 0 {
280	        diagnostics.push(skipped(
281	            None,
282	            format!("{} directory walk errors did not name a UTF-8 path", found.walk_errors_without_path),
283	        ));
284	    }
285	    diagnostics
286	}
287	
288	/// What block retrieval needs besides the file itself.
289	struct FileContext<'a> {
290	    registry: &'a AnalyzerRegistry,
291	    plan: &'a QueryPlan,
292	    matchers: &'a [RegexMatcher],
293	    language: Option<Language>,
294	    allow_tests: bool,
295	}
296	
297	/// One analyzer can own several languages (TypeScript's owns JavaScript too), so the `--language` filter goes by
298	/// extension.
299	fn has_language_extension(language: Language, path: &Utf8Path) -> bool {
300	    match language {
301	        Language::TypeScript => matches!(path.extension(), Some("ts" | "tsx" | "mts" | "cts")),
302	        Language::JavaScript => matches!(path.extension(), Some("js" | "jsx" | "mjs" | "cjs")),
303	        Language::Rust => path.extension() == Some("rs"),
304	        Language::Python => false,
305	    }
306	}
307	
308	/// Analyzes one surviving file and pushes the annotated blocks that contain a matching line onto `out`.
309	fn retrieve_blocks(
310	    ctx: &FileContext<'_>,
311	    path: &Utf8Path,
312	    hits: &[LineHit],
313	    read: &dyn Fn(&Utf8Path) -> io::Result<Source>,
314	    out: &mut Vec<(CodeBlock, Vec<String>)>,
315	    diagnostics: &mut Vec<Diagnostic>,
316	) {
317	    let Some(analyzer) = ctx.registry.analyzer_for(path) else { return };
318	    if ctx.language.is_some_and(|language| !has_language_extension(language, path)) {
319	        return;
320	    }
321	    let Source { text, lossy } = match read(path) {
322	        Ok(source) => source,
323	        Err(err) => {
324	            diagnostics.push(skipped(Some(path), format!("could not read source: {err}")));
325	            return;
326	        }
327	    };
328	    if lossy {
329	        diagnostics.push(Diagnostic {
330	            kind: DiagnosticKind::LossyRead,
331	            path: Some(path.to_owned()),
332	            message: "invalid UTF-8 replaced with U+FFFD".to_owned(),
333	        });
334	    }
335	    let analysis = match analyzer.analyze(path, Box::new(move || Ok(text))) {
336	        Ok(analysis) => analysis,
337	        Err(err) => {
338	            diagnostics.push(skipped(Some(path), format!("could not analyze: {err}")));
339	            return;
340	        }
341	    };
342	    if analysis.had_parse_errors {
343	        let message = analysis
344	            .degradation
345	            .map_or_else(|| "parse errors; blocks may be incomplete".to_owned(), |reason| reason.to_string());
346	        diagnostics.push(Diagnostic { kind: DiagnosticKind::Degraded, path: Some(path.to_owned()), message });
347	    }
348	    let positive: Vec<&RegexMatcher> = ctx
349	        .plan
350	        .terms
351	        .iter()
352	        .zip(ctx.matchers)
353	        .filter(|(term, _)| term.modifier != Modifier::Excluded)
354	        .map(|(_, matcher)| matcher)
355	        .collect();
356	    let line_matches = |text: &str| positive.iter().any(|matcher| matches_text(matcher, text));
357	    // Test blocks always take part in deciding which block owns a hit, so a test method inside a regular `impl` or trait
358	    // does not leak its matches to the holder; they are returned only when asked for. Only references are collected, so
359	    // no block is copied.
360	    let blocks: Vec<&CodeBlock> = analysis.blocks.iter().chain(&analysis.test_blocks).collect();
361	    let returned = if ctx.allow_tests { blocks.len() } else { analysis.blocks.len() };
362	    for (block, inside) in blocks.iter().zip(owned_hits(&blocks, hits, &line_matches)).take(returned) {
363	        if inside.is_empty() {
364	            continue;
365	        }
366	        let matched_keywords = ctx
367	            .plan
368	            .terms
369	            .iter()
370	            .zip(ctx.matchers)
371	            .filter(|(term, _)| term.modifier != Modifier::Excluded)
372	            .filter(|(_, matcher)| inside.iter().any(|hit| matches_text(matcher, &hit.text)))
373	            .map(|(term, _)| keyword(term))
374	            .collect();
375	        let annotated = CodeBlock {
376	            matched_lines: inside.iter().map(|hit| hit.line_number).collect(),
377	            matched_keywords,
378	            ..(*block).clone()
379	        };
380	        let tokens = tokenize_block(&annotated);
381	        out.push((annotated, tokens));
382	    }
383	}
384	
385	/// Splits `hits` among `blocks`: a hit goes to every block whose own text on that line matches, except one that holds
386	/// a smaller such block. A class or object therefore keeps only the matches outside its members, and a block with
387	/// none is dropped by the caller. A block can start or end in the middle of a line (`} b() {`, `}, // note`), so only
388	/// the part of the line inside the block counts, which sends the match to the member or holder that actually contains
389	/// the text. Where no block's own text matches (a match across the edge of every block on the line) every block on the
390	/// line keeps the hit, so a match is never lost. Blocks that only share a line are not nested, so each keeps it: blocks
391	/// with the same line range (`mod m { #[cfg(test)] fn f() {} }` on one line) are nested only when the larger one's text
392	/// contains the other's.
393	/// `hits` must be in line order; each block's hits are too.
394	fn owned_hits<'h>(
395	    blocks: &[&CodeBlock],
396	    hits: &'h [LineHit],
397	    line_matches: &dyn Fn(&str) -> bool,
398	) -> Vec<Vec<&'h LineHit>> {
399	    let mut containing: Vec<Vec<usize>> = vec![Vec::new(); hits.len()];
400	    for (index, block) in blocks.iter().enumerate() {
401	        let first = hits.partition_point(|hit| hit.line_number < block.line_start);
402	        let inside = hits[first..].iter().take_while(|hit| hit.line_number <= block.line_end).count();
403	        for slot in &mut containing[first..first + inside] {
404	            slot.push(index);
405	        }
406	    }
407	    let own_text_matches = |index: usize, line: usize| {
408	        let block = blocks[index];
409	        block.code.split('\n').nth(line - block.line_start).is_some_and(line_matches)
410	    };
411	    let holds = |outer: usize, inner: usize| {
412	        let (outer, inner) = (blocks[outer], blocks[inner]);
413	        let within = inner.line_start >= outer.line_start && inner.line_end <= outer.line_end;
414	        let same_lines = (inner.line_start, inner.line_end) == (outer.line_start, outer.line_end);
415	        within && (!same_lines || (inner.code.len() < outer.code.len() && outer.code.contains(&inner.code)))
416	    };
417	    let mut per_block = vec![Vec::new(); blocks.len()];
418	    for (hit, containing_all) in hits.iter().zip(&containing) {
419	        let matching: Vec<usize> =
420	            containing_all.iter().copied().filter(|&index| own_text_matches(index, hit.line_number)).collect();
421	        let candidates = if matching.is_empty() { containing_all } else { &matching };
422	        for &outer in candidates {
423	            if !candidates.iter().any(|&inner| holds(outer, inner)) {
424	                per_block[outer].push(hit);
425	            }
426	        }
427	    }
428	    per_block
429	}
430	
431	/// Returns the text the user typed for `term`: a regex as written, a literal with its escaping undone.
432	fn keyword(term: &ParsedTerm) -> String {
433	    if term.is_regex {
434	        return term.pattern.clone();
435	    }
436	    // `regex::escape` only ever puts a backslash before the character it escapes.
437	    let mut text = String::with_capacity(term.pattern.len());
438	    let mut chars = term.pattern.chars();
439	    while let Some(ch) = chars.next() {
440	        if ch == '\\' {
441	            text.extend(chars.next());
442	        } else {
443	            text.push(ch);
444	        }
445	    }
446	    text
447	}
448	
449	/// Returns the BM25 query terms: the tokens of each non-excluded literal term, each once, in query order.
450	fn bm25_terms(plan: &QueryPlan) -> Vec<String> {
451	    let mut seen = FxHashSet::default();
452	    plan.terms
453	        .iter()
454	        .filter(|term| term.modifier != Modifier::Excluded && !term.is_regex)
455	        .flat_map(|term| tokenize(&keyword(term)))
456	        .filter(|token| seen.insert(token.clone()))
457	        .collect()
458	}
459	
460	/// Counts, for each query term, the blocks whose tokens contain it at least once.
461	fn document_frequencies(blocks: &[(CodeBlock, Vec<String>)], terms: &[String]) -> FxHashMap<String, usize> {
462	    let mut df = FxHashMap::default();
463	    for (_, tokens) in blocks {
464	        let present: FxHashSet<&str> = tokens.iter().map(String::as_str).collect();
465	        for term in terms.iter().filter(|term| present.contains(term.as_str())) {
466	            *df.entry(term.clone()).or_insert(0) += 1;
467	        }
468	    }
469	    df
470	}
