516	            source: Box<dyn FnOnce() -> Result<String>>,
517	            profile: AnalysisProfile,
518	        ) -> Result<Arc<FileAnalysis>> {
519	            let source = source()?;
520	            let (blocks, had_parse_errors) = (self.make)(path, &source)?;
521	            Ok(Arc::new(FileAnalysis {
522	                source_path: path.to_owned(),
523	                digest: Digest::blake3(source.as_bytes()),
524	                profile,
525	                had_parse_errors,
526	                degradation: self.degradation,
527	                symbols: Vec::new(),
528	                dependencies: Vec::new(),
529	                exports: Vec::new(),
530	                blocks,
531	                test_blocks: Vec::new(),
532	                lang: LangData::Ts(TsData::default()),
533	            }))
534	        }
535	    }
536	
537	    fn registry(
538	        make: impl Fn(&Utf8Path, &str) -> Result<(Vec<CodeBlock>, bool)> + Send + Sync + 'static,
539	    ) -> AnalyzerRegistry {
540	        AnalyzerRegistry::new(vec![Arc::new(Canned { make: Box::new(make), degradation: None })])
541	    }
542	
543	    /// Lines `start..=end` (1-based) of `source` as a function block.
544	    fn block(path: &Utf8Path, source: &str, start: usize, end: usize) -> CodeBlock {
545	        let code: Vec<&str> = source.lines().skip(start - 1).take(end - start + 1).collect();
546	        CodeBlock {
547	            file: path.to_owned(),
548	            line_start: start,
549	            line_end: end,
550	            node_kind: SymbolKind::Function,
551	            code: code.join("\n"),
552	            symbol_signature: None,
553	            matched_lines: Vec::new(),
554	            matched_keywords: Vec::new(),
555	            parent: None,
556	        }
557	    }
558	
559	    /// One block per file covering all of it.
560	    fn whole_file_registry() -> AnalyzerRegistry {
561	        registry(|path, source| Ok((vec![block(path, source, 1, source.lines().count().max(1))], false)))
562	    }
563	
564	    fn tree(files: &[(&str, &str)]) -> (tempfile::TempDir, Utf8PathBuf) {
565	        let dir = tempfile::tempdir().unwrap();
566	        for (name, content) in files {
567	            let path = dir.path().join(name);
568	            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
569	            std::fs::write(path, content).unwrap();
570	        }
571	        let root = Utf8PathBuf::from_path_buf(dir.path().canonicalize().unwrap()).unwrap();
572	        (dir, root)
573	    }
574	
575	    fn request<'a>(root: &'a Utf8Path, query: &'a str) -> SearchRequest<'a> {
576	        SearchRequest { root, query, exact: false, allow_tests: false, respect_ignore_files: true, language: None }
577	    }
578	
579	    /// The ranked files relative to `root`, in rank order.
580	    fn files(result: &SearchResult, root: &Utf8Path) -> Vec<String> {
581	        result.ranked.iter().map(|ranked| ranked.block.file.strip_prefix(root).unwrap().to_string()).collect()
582	    }
583	
584	    fn summary(diagnostics: &[Diagnostic]) -> Vec<(DiagnosticKind, Option<&str>, &str)> {
585	        diagnostics.iter().map(|d| (d.kind, d.path.as_ref().map(|p| p.as_str()), d.message.as_str())).collect()
586	    }
