917	    /// The class `Foo` (lines 1-9) with the methods `alpha` (3-5) and `beta` (6-8), as the TypeScript analyzer emits them.
918	    fn class_registry() -> AnalyzerRegistry {
919	        registry(|path, source| {
920	            let parent = ParentContext { kind: SymbolKind::Class, name: "Foo".to_owned(), line: 1 };
921	            let member = |start, end| CodeBlock {
922	                node_kind: SymbolKind::Method,
923	                parent: Some(parent.clone()),
